    "workflow",
    "tdd",
    "code-review",
    "git",
    "pr",
    "orchestration"
  ],
  "license": "MIT",
  "userConfig": {
    "pr_size_budget": {
      "type": "number",
      "title": "PR size budget (LOC)",
      "description": "Soft LOC budget per PR (additions+deletions, post-exclusion) enforced by the ship/flow/stack-pr gate",
      "default": 300
    },
    "protected_branches": {
      "type": "string",
      "title": "Protected branches",
      "description": "Comma-separated branch names guarded by the confirm-to-commit hook",
      "default": "main,master,develop"
    },
    "skip_tool_check": {
      "type": "boolean",
      "title": "Skip tool check",
      "description": "Skip the SessionStart CLI dependency pre-flight",
      "default": false
    },
    "learn_from_outcomes": {
      "type": "boolean",
      "title": "Learn from outcomes",
      "description": "Record verified debug outcomes into the local Graphify work-memory (graphify-out/, git-ignored) so code discovery improves across sessions. No effect when Graphify is absent.",
      "default": true
    },
    "interaction_policy": {
      "type": "string",
      "title": "Interaction policy",
      "description": "Default autopilot level for inward gates: manual (every gate asks), guided (mechanical confirms auto-advance), auto (sprint contract; phases run autonomously against agreed criteria). Outward-facing gates (tracker writes, PR review posting, evidence publish) always ask regardless.",
      "default": "manual"
    },
    "statusline": {
      "type": "boolean",
      "title": "Statusline",
      "description": "Render the orc statusline (session, phase, branch, PR, context, cost). false hides it even with the plugin-shipped default installed.",
      "default": true
    },
    "statusline_style": {
